def count_beautiful_integers(low: int, high: int, k: int) -> int:
    def is_beautiful(n: int) -> bool:
        even_count, odd_count = 0, 0
        while n > 0:
            digit = n % 10
            if digit % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
            n //= 10
        return even_count == odd_count and n % k == 0

    return sum(is_beautiful(i) for i in range(low, high + 1))
